insert into public.tasks (title, description, expected_result, difficulty, topic, hints)
values
('Кнопка с откликом при наведении', 'Создай заметную кнопку действия, которая плавно меняет цвет и слегка приподнимается при наведении курсора.', 'Плавный эффект при наведении и видимый фокус клавиатуры.', 1, 'Кнопки', '["Определи исходный и наведённый вид.", "Добавь плавность и фокус клавиатуры."]'),
('Переключатель темы', 'Добавь кнопку, которая переключает страницу между светлой и тёмной темами.', 'Тема меняется по нажатию, текст и элементы остаются читаемыми.', 1, 'Кнопки', '["Продумай два состояния.", "Убедись, что контраст сохраняется."]'),
('Кнопка копирования', 'Сделай кнопку копирования текста с подтверждением, что действие выполнено.', 'Текст копируется и результат действия подтверждается.', 1, 'Кнопки', '["Используй API буфера обмена.", "Добавь короткое состояние успеха."]'),
('Пустое состояние списка', 'Покажи дружелюбное сообщение, когда список пока не содержит элементов.', 'Пустой список не выглядит как ошибка и подсказывает следующий шаг.', 1, 'Списки и данные', '["Не полагайся только на иллюстрацию.", "Предложи пользователю действие."]'),
('Индикатор загрузки', 'Покажи анимированный индикатор на время ожидания ответа и подпись для доступности.', 'Индикатор сообщает о загрузке и учитывает уменьшение анимации.', 1, 'Анимации', '["Добавь текстовую подпись.", "Учитывай системную настройку анимации."]'),
('Адаптивная карточка', 'Сделай карточку с заголовком и описанием, которая хорошо выглядит на узком экране.', 'Текст не выходит за границы, карточка удобна на телефоне.', 1, 'Адаптив', '["Начни с мобильного размера.", "Проверь длинный заголовок."]'),
('Форма обратной связи', 'Собери форму с именем, email и сообщением с проверкой обязательных полей.', 'Ошибки показаны рядом с полями, успешная отправка подтверждается.', 2, 'Формы', '["Проверь каждое поле.", "Свяжи ошибки с полями."]'),
('Поиск по списку', 'Добавь поле поиска, которое фильтрует список карточек без перезагрузки страницы.', 'Список обновляется при вводе и имеет пустое состояние.', 2, 'Списки и данные', '["Сравнивай без учёта регистра.", "Покажи отсутствие совпадений."]'),
('Адаптивная сетка', 'Сделай сетку карточек для телефона, планшета и широкого экрана.', 'Нет горизонтальной прокрутки, карточки остаются читаемыми.', 2, 'Адаптив', '["Начни с узкого экрана.", "Проверь несколько размеров."]'),
('Список задач', 'Сделай список задач с отметками выполнения и счётчиком выполненных пунктов.', 'Статус пункта меняется, счётчик актуален.', 2, 'Списки и данные', '["Храни статус каждого пункта.", "Обновляй счётчик автоматически."]'),
('Раскрывающийся блок', 'Добавь раскрывающийся блок с плавной анимацией и доступным состоянием.', 'Блок открывается и закрывается мышью и клавиатурой.', 2, 'Анимации', '["Сделай состояние явным.", "Учитывай уменьшение анимации."]'),
